import hashlib
import hmac
import json

from payhook.errors import InvalidNotification


def _get_header(headers, name):
    target = name.lower()
    for key, value in headers.items():
        if key.lower() == target:
            return value
    return None


def parse_payment(raw_body, headers, secret, now):
    """Return an accepted payment in the billing worker's normalized format."""
    if not isinstance(raw_body, (bytes, bytearray)):
        raise InvalidNotification("body must be bytes")
    body = bytes(raw_body)

    stamp = _get_header(headers, "X-Pay-Timestamp")
    signature = _get_header(headers, "X-Pay-Signature")
    if not isinstance(stamp, str) or not isinstance(signature, str):
        raise InvalidNotification("missing timestamp or signature header")

    # Timestamp: decimal Unix timestamp within 300s of now.
    stamp_clean = stamp.strip()
    if not stamp_clean or stamp_clean[0] in "+-":
        # A leading sign is not a decimal Unix timestamp per the wire format.
        if not (stamp_clean.startswith("-") and stamp_clean[1:].isdigit()):
            if not stamp_clean.lstrip("+-").isdigit() or stamp_clean.startswith("+"):
                raise InvalidNotification("malformed timestamp")
    if not stamp_clean.isdigit():
        raise InvalidNotification("malformed timestamp")
    try:
        timestamp = int(stamp_clean)
    except ValueError:
        raise InvalidNotification("malformed timestamp")
    if abs(timestamp - now) > 300:
        raise InvalidNotification("stale timestamp")

    # Signature: v1=<hex digest> of HMAC-SHA256 over ascii(stamp) + b"." + body.
    if not signature.startswith("v1="):
        raise InvalidNotification("unsupported signature scheme")
    provided = signature[len("v1="):]
    try:
        ascii_stamp = stamp.encode("ascii")
    except UnicodeEncodeError:
        raise InvalidNotification("malformed timestamp")
    expected = hmac.new(
        secret, ascii_stamp + b"." + body, hashlib.sha256
    ).hexdigest()
    if not hmac.compare_digest(provided, expected):
        raise InvalidNotification("signature mismatch")

    # Body: UTF-8 JSON object with required fields.
    try:
        text = body.decode("utf-8")
    except UnicodeDecodeError:
        raise InvalidNotification("body is not valid UTF-8")
    try:
        payload = json.loads(text)
    except (ValueError, json.JSONDecodeError):
        raise InvalidNotification("malformed JSON")
    if not isinstance(payload, dict):
        raise InvalidNotification("payload must be a JSON object")

    event_id = payload.get("event_id")
    account_id = payload.get("account_id")
    amount_minor = payload.get("amount_minor")
    currency = payload.get("currency")

    if not isinstance(event_id, str) or not event_id:
        raise InvalidNotification("invalid event_id")
    if not isinstance(account_id, str) or not account_id:
        raise InvalidNotification("invalid account_id")
    if not isinstance(amount_minor, int) or isinstance(amount_minor, bool):
        raise InvalidNotification("invalid amount_minor")
    if amount_minor < 0:
        raise InvalidNotification("invalid amount_minor")
    if (
        not isinstance(currency, str)
        or len(currency) != 3
        or not currency.isascii()
        or not currency.isupper()
        or not currency.isalpha()
    ):
        raise InvalidNotification("invalid currency")

    return {
        "event_id": event_id,
        "account_id": account_id,
        "amount_minor": amount_minor,
        "currency": currency,
    }

